export const PROCUREMENT_TOTAL_VALUE_INR = PROCUREMENT_ITEMS.reduce(
  (sum, item) => sum + item.totalPriceInr,
  0
);

export const PROCUREMENT_STATUS_META: Record<
  ProcurementStatus,
  { label: string; badgeVariant: "accent" | "success" | "info" | "warning" | "danger" | "secondary" | "outline" }
> = {
  RECEIVED: { label: "Received", badgeVariant: "accent" },
  PAYMENT_DONE: { label: "Payment Done", badgeVariant: "success" },
  PR_RAISED: { label: "PR Raised", badgeVariant: "info" },
  QUOTATION_RECEIVED: { label: "Quotation", badgeVariant: "warning" },
  PENDING: { label: "Pending", badgeVariant: "secondary" },
  UNAVAILABLE: { label: "Unavailable", badgeVariant: "danger" },
  DRAFT: { label: "Draft / Needs Specs", badgeVariant: "outline" },
};

export function extractItemProcurementMeta(
  specifications: Record<string, unknown> | null | undefined
): {
  labBlock: string | null;
  vendorActual: string | null;
  vendorResearch: string | null;
  productUrl: string | null;
  unitPriceInr: number | null;
  procurementQty: number | null;
  totalPriceInr: number | null;
  procurementStatus: ProcurementStatus | null;
  allocationScope: AllocationScope | null;
  remarks: string | null;
} {
  if (!specifications) {
    return {
      labBlock: null,
      vendorActual: null,
      vendorResearch: null,
      productUrl: null,
      unitPriceInr: null,
      procurementQty: null,
      totalPriceInr: null,
      procurementStatus: null,
      allocationScope: null,
      remarks: null,
    };
  }
  return {
    labBlock: typeof specifications.labBlock === "string" ? specifications.labBlock : null,
    vendorActual: typeof specifications.vendorActual === "string" ? specifications.vendorActual : null,
    vendorResearch: typeof specifications.vendorResearch === "string" ? specifications.vendorResearch : null,
    productUrl: typeof specifications.productUrl === "string" ? specifications.productUrl : null,
    unitPriceInr: typeof specifications.unitPriceInr === "number" ? specifications.unitPriceInr : null,
    procurementQty: typeof specifications.procurementQty === "number" ? specifications.procurementQty : null,
    totalPriceInr: typeof specifications.totalPriceInr === "number" ? specifications.totalPriceInr : null,
    procurementStatus:
      typeof specifications.procurementStatus === "string"
        ? (specifications.procurementStatus as ProcurementStatus)
        : null,
    allocationScope:
      specifications.allocationScope === "ALL_40_LABS" ||
      specifications.allocationScope === "PER_CAMPUS"
        ? specifications.allocationScope
        : null,
    remarks: typeof specifications.remarks === "string" ? specifications.remarks : null,
  };
}

export function formatInr(amount: number): string {
  return new Intl.NumberFormat("en-IN", {
    style: "currency",
    currency: "INR",
    maximumFractionDigits: amount >= 1000 ? 0 : 2,
  }).format(amount);
}
